  /* Card-level links (Oct 17 audit): every matched card names its own
     competency, so a card answer credits that one competency instead of
     every competency in its topic. Keyed the way recall stores progress:
     legacy cards by lt:lid, newer cards by topic id and card id. */
  if (MAP) {
    B.modules.forEach(function (m) {
      (m.topics || []).forEach(function (t) {
        (t.cards || []).forEach(function (c) {
          if (!c.competencyId) return;
          var e = { title: t.title, comps: [c.competencyId], card: true };
          if (c.lt && c.lid) MAP[c.lt + ':' + c.lid] = e;
          MAP[t.id + ':' + c.id] = e;
        });
      });
    });
  }
  window.BIO004_TOPIC_COMPS = EXTRA;
